// interval
reg09 = 1/12;
// distance
reg12 = 3;
// "skip-behind-camera"-distance
reg13 = -2.7;
//scope settings  (standard radius and amplitude multiplier)
reg60 = 1;
reg61 = .5;
// movement offsets
rotsign = .5;
change = -ph;
side = -ph;
// mouse movement off
en = 0;
// speed offsets
speed1 = 1;
speed = 1;
t = gettime(0);
ctrl2 = 1;
n = 0;

code.perFrame:
 // fps-independance and size settings
speed = (gettime(0)-t)*20;
speed1 = (speed+speed1)*.5;
reg00 = w/h;
hw = h+w;
reg95 = hw*.01;       // thingies linesize offset
reg97 = hw*.00366; // tube linesize offset

  // time vars
pause = band(equal(gettime(-1.0),t4),gettime(-1.0));
reg90 = pause;
reg88 = gettime(-1.0); reg89 = gettime(-2.0);
t = gettime(0);
t2 = if(above(t-t1,1),assign(t1,t),0);
t2 = if(b,1,t2);

  //get scope data every second and on beat
in = 0;
if(t2,loop(reg99,exec2(assign(gmegabuf(in),(getosc(in*reg98,reg98,0))),assign(in,in+1))),bla);

  // front SSC (faded scope-data)
in = reg99;                                                                                                                                              //    v-----fading speed (>1)
if(pause,bla,loop(reg99,exec2(assign(gmegabuf(in),gmegabuf(in)-(gmegabuf(in)-gmegabuf(in-reg99))*min(.9,.1*speed)),assign(in,in+1))));

  // follw-up scope-data (from tail to second SSC!)
num = 1;
if(pause,bla,loop(reg30-1,exec3(assign(in,0),loop(reg99,exec2(assign(gmegabuf(reg30*reg99-num+in),gmegabuf(reg30*reg99-reg99-num+in)),assign(in,in+1))),assign(num,num+reg99) ) ));

  // position counter (re)settings
reg08 = 0-reg09;
reg30 = 0;
reg32 = 2/reg31;
reg31 = 0;

  // "beat bulge" movement
spd_pse = .2*speed*(1-pause);
reg15 = reg15+spd_pse;
reg16 = reg16+spd_pse;
reg17 = reg17+spd_pse;
reg18 = reg18+spd_pse;
reg19 = reg19+spd_pse;
reg20 = reg20+spd_pse;
reg21 = reg21+spd_pse;

  // light brightness (more is less!)
reg62 = reg62-(reg62-.7)*.0625;
  // lightning amount + loudness (more IS more!)
loudness = loudness-(loudness-getspec(.3,.55,0)*.75)*min(.5,.125*speed);
reg63 = .5+loudness; reg64 = loudness;

// on pause stop
loudness = if(equal(gettime(-1.0),t4),0,loudness);
t4 = gettime(-1.0);

  // mouse button change
en = getkbmouse(3)+getkbmouse(4);

 // x- and y-mouse
mx = getkbmouse(1);
my = getkbmouse(2);

  // rotations
onscreen = band(below(abs(mx),1.1),below(abs(my),1.1));
r = r+loudness*rotsign*speed; d = .4;
rx = if(band(en,onscreen),-$PI*my*.5-$PI*.5,cos(r)*d*ph-ph); 
ry = if(band(en,onscreen),$PI*mx,sin(r)*d*ph+side);
side = side-(side-change)*min(.1,.03125*speed);
change = if(band(b,above(gettime(0)-t3,20)),exec2(assign(t3,gettime(0)),-change),change);
rz = 0;

 // zoom on side-change
reg12 = 3-if(en,0,cos(side)*1.5);
reg13 = -reg12*.9;

reg01 = sin(rx); reg02 = cos(rx);
reg03 = sin(ry); reg04 = cos(ry);
reg05 = sin(rz); reg06 = cos(rz);


   // interface commands
ctrl = getkbmouse(17);
ctrl2 = if(ctrl,if(bnot(equal(ctrl,lastctrl)),1-ctrl2,ctrl2),ctrl2);
reg51 = onscreen*ctrl2;
lastctrl = ctrl;

    // color code by ASD5A!  thx! ^-^
 /*
hsl to rgb body
hue light            reg53
saturation light   reg54
brightness light  reg55
hue body            reg56
saturation body   reg57
brightness body  reg58
*/
 // one for the lighting color...
hues1=reg53;
s1=reg54;
bri1=reg55;
hue1=360*(hues1-floor(hues1));

hi1=floor(hue1/60);
f1=hue1/60-hi1;
p1=bri1*(1-s1);
q1=bri1*(1-(s1*f1));
t11=bri1*(1-(s1*(1-f1)));

red1=equal(hi1,0)*bri1+equal(hi1,1)*q1+equal(hi1,2)*p1+equal(hi1,3)*p1+equal(hi1,4)*t11+equal(hi1,5)*bri1;
blue1=equal(hi1,0)*p1+equal(hi1,1)*p1+equal(hi1,2)*t11+equal(hi1,3)*bri1+equal(hi1,4)*bri1+equal(hi1,5)*q1;
green1=equal(hi1,0)*t11+equal(hi1,1)*bri1+equal(hi1,2)*bri1+equal(hi1,3)*q1+equal(hi1,4)*p1+equal(hi1,5)*p1;

reg41=1-red1;
reg43=1-green1;
reg45=1-blue1;


 // ... and one for the body color
hues=reg56;
s=reg57;
bri=reg58;
hue=360*(hues-floor(hues));

hi=floor(hue/60);
f=hue/60-hi;
p=bri*(1-s); 
q=bri*(1-(s*f));
t12=bri*(1-(s*(1-f)));

red=equal(hi,0)*bri+equal(hi,1)*q+equal(hi,2)*p+equal(hi,3)*p+equal(hi,4)*t12+equal(hi,5)*bri;
blue=equal(hi,0)*p+equal(hi,1)*p+equal(hi,2)*t12+equal(hi,3)*bri+equal(hi,4)*bri+equal(hi,5)*q;
green=equal(hi,0)*t12+equal(hi,1)*bri+equal(hi,2)*bri+equal(hi,3)*q+equal(hi,4)*p+equal(hi,5)*p;

reg42=1-red;
reg44=1-green;
reg46=1-blue;

code.onBeat:
// invert rotation
rotsign = rotsign*(above(rand(100),10*loudness)*2-1);
// set beat bulge to start
reg15 = if(equal(bcount,0),exec2(assign(reg22,sqr(loudness*3)+.5),-.5),reg15);
reg16 = if(equal(bcount,1),exec2(assign(reg23,sqr(loudness*3)+.5),-.5),reg16);
reg17 = if(equal(bcount,2),exec2(assign(reg24,sqr(loudness*3)+.5),-.5),reg17);
reg18 = if(equal(bcount,3),exec2(assign(reg25,sqr(loudness*3)+.5),-.5),reg18);
reg19 = if(equal(bcount,4),exec2(assign(reg26,sqr(loudness*3)+.5),-.5),reg19);
reg20 = if(equal(bcount,5),exec2(assign(reg27,sqr(loudness*3)+.5),-.5),reg20);
reg21 = if(equal(bcount,6),exec2(assign(reg28,sqr(loudness*3)+.5),-.5),reg21);
bcount = (bcount+1)%7;
// brightness on beat (more is less!)
reg62 = .6;

